1	/**
2	 * MLflow tracing integration for Qwen Code.
3	 *
4	 * Parses the current turn from a Qwen Code JSONL transcript and emits an
5	 * MLflow trace shaped like the opencode/Claude Code integration:
6	 *
7	 *   AGENT qwen_code_conversation
8	 *   ├─ LLM  llm_call  (one per assistant record; messages + tool_calls in OpenAI chat format)
9	 *   └─ TOOL tool_<name>  (one per functionCall; paired with tool_result by callId)
10	 *
11	 * Qwen-specific semantics:
12	 * - An assistant record may emit both `thought` text (internal reasoning,
13	 *   excluded from Chat rendering) and user-facing text in the same parts
14	 *   list, plus zero or more functionCall parts.
15	 * - Tool results appear as standalone `tool_result` records with a
16	 *   `toolCallResult: {callId, status, resultDisplay}` block. Status values
17	 *   observed in real transcripts are `success` and `cancelled`; we treat
18	 *   anything other than `success` as a failure.
19	 */
20	
21	import {
22	  startSpan,
23	  flushTraces,
24	  InMemoryTraceManager,
25	  SpanStatusCode,
26	  SpanType,
27	  SpanAttributeKey,
28	  TraceMetadataKey,
29	  TokenUsageKey,
30	  type LiveSpan,
31	} from '@mlflow/core';
32	
33	import type { ChatMessage, ChatRecord, FunctionCall, ToolCall } from './types.js';
34	import {
35	  buildToolResultMap,
36	  getFunctionCalls,
37	  getLastTurnRecords,
38	  getMessageText,
39	  getTokenUsage,
40	  getToolOutput,
41	  parseTimestampToNs,
42	  readTranscript,
43	} from './transcript.js';
44	
45	const SUCCESS_STATUS = 'success';
46	
47	/**
48	 * Process a Qwen Code transcript and create an MLflow trace for the last turn.
49	 */
50	export async function processTranscript(
51	  transcriptPath: string | null,
52	  sessionId?: string,
53	): Promise<void> {
54	  if (!transcriptPath) {
55	    return;
56	  }
57	
58	  const records = readTranscript(transcriptPath);
59	  if (records.length === 0) {
60	    return;
61	  }
62	
63	  const turn = getLastTurnRecords(records);
64	  if (turn.length === 0) {
65	    return;
66	  }
67	
68	  // Map tool_result records by callId so we can pair tool calls with results
69	  const toolResults = buildToolResultMap(turn);
70	
71	  const userRecord = turn[0];
72	  const userPrompt = getMessageText(userRecord);
73	  const resolvedSessionId = sessionId ?? userRecord.sessionId ?? `qwen-${Date.now()}`;
74	  const model = firstAssistantModel(turn) ?? 'unknown';
75	
76	  const turnStartNs = parseTimestampToNs(userRecord.timestamp);
77	  const turnEndNs = parseTimestampToNs(turn[turn.length - 1].timestamp);
78	
79	  // Compute the final assistant response upfront so it can feed both the
80	  // root span output and trace preview.
81	  const finalResponse = findFinalAssistantText(turn);
82	
83	  // Create root AGENT span. Pass the user prompt as a raw string so MLflow
84	  // auto-generates a clean request preview; opencode-style `{prompt: ...}`
85	  // wrapping doesn't render cleanly in the session view.
86	  const rootSpan = startSpan({
87	    name: 'qwen_code_conversation',
88	    spanType: SpanType.AGENT,
89	    inputs: userPrompt,
90	    attributes: { model },
91	    ...(turnStartNs != null ? { startTimeNs: turnStartNs } : {}),
92	  });
93	
94	  createChildSpans(rootSpan, turn, model, toolResults);
95	
96	  const tokenUsage = aggregateTokenUsage(turn);
97	  if (tokenUsage) {
98	    rootSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {
99	      [TokenUsageKey.INPUT_TOKENS]: tokenUsage.input,
100	      [TokenUsageKey.OUTPUT_TOKENS]: tokenUsage.output,
101	      [TokenUsageKey.TOTAL_TOKENS]: tokenUsage.total,
102	    });
103	  }
104	
105	  // Attach session/user metadata. updateCurrentTrace() requires an active
106	  // OTel span context which hook-based integrations don't have, so we go
107	  // through InMemoryTraceManager directly — same pattern as codex/opencode.
108	  const traceId = rootSpan.traceId;
109	  if (traceId) {
110	    const traceManager = InMemoryTraceManager.getInstance();
111	    const trace = traceManager.getTrace(traceId);
112	    if (trace) {
113	      trace.info.traceMetadata = {
114	        ...trace.info.traceMetadata,
115	        [TraceMetadataKey.TRACE_SESSION]: resolvedSessionId,
116	        [TraceMetadataKey.TRACE_USER]: process.env.USER ?? '',
117	      };
118	    }
119	  }
120	
121	  rootSpan.end({
122	    outputs: finalResponse ?? '',
123	    ...(turnEndNs != null ? { endTimeNs: turnEndNs } : {}),
124	  });
125	
126	  await flushTraces();
127	}
128	
129	/**
130	 * Create LLM and TOOL child spans by walking the turn chronologically.
131	 *
132	 * Timing model (mirrors the codex integration):
133	 * - LLM span: [previous boundary] → [assistant record timestamp]
134	 *   where the previous boundary is the turn's first record or the most
135	 *   recent `tool_result` — i.e. the point at which the LLM had all the
136	 *   context it needed to produce this response.
137	 * - TOOL span: [assistant record timestamp] → [matching tool_result
138	 *   timestamp], looked up by callId. Falls back to the assistant
139	 *   timestamp if the tool_result is missing (tool still in-flight).
140	 */
141	export function createChildSpans(
142	  parentSpan: LiveSpan,
143	  turn: ChatRecord[],
144	  fallbackModel: string,
145	  toolResults: Map<string, ChatRecord>,
146	): void {
147	  let prevBoundaryNs: number | null = parseTimestampToNs(turn[0]?.timestamp);
148	
149	  for (let i = 0; i < turn.length; i++) {
150	    const record = turn[i];
151	    const timestampNs = parseTimestampToNs(record.timestamp);
152	    if (timestampNs == null) {
153	      continue;
154	    }
155	
156	    if (record.type === 'tool_result') {
157	      // Tool results are not spans themselves; they end the preceding
158	      // TOOL span and form a new boundary for the next LLM span.
159	      prevBoundaryNs = timestampNs;
160	      continue;
161	    }
162	
163	    if (record.type !== 'assistant') {
164	      // Skip user (already represented by root inputs) and system records
165	      // (internal framing — not visible to end users).
166	      continue;
167	    }
168	
169	    const model = record.model ?? fallbackModel;
170	    const text = getMessageText(record);
171	    const functionCalls = getFunctionCalls(record);
172	
173	    // Assistant records with no text AND no functionCalls represent purely
174	    // internal state (unlikely but defensive) — skip them entirely.
175	    if (!text.trim() && functionCalls.length === 0) {
176	      continue;
177	    }
178	
179	    createLlmSpan(parentSpan, turn, i, prevBoundaryNs, timestampNs, model, text, functionCalls);
180	
181	    for (const call of functionCalls) {
182	      createToolSpan(parentSpan, call, timestampNs, toolResults);
183	    }
184	
185	    prevBoundaryNs = timestampNs;
186	  }
187	}
188	
189	function createLlmSpan(
190	  parentSpan: LiveSpan,
191	  turn: ChatRecord[],
192	  assistantIndex: number,
193	  prevBoundaryNs: number | null,
194	  assistantTimestampNs: number,
195	  model: string,
196	  text: string,
197	  functionCalls: FunctionCall[],
198	): void {
199	  const messages = reconstructMessages(turn, assistantIndex);
200	  const toolCalls = toOpenAIToolCalls(functionCalls);
201	
202	  const assistantOutput: ChatMessage = {
203	    role: 'assistant',
204	    content: text.trim() ? text : null,
205	    ...(toolCalls.length > 0 ? { tool_calls: toolCalls } : {}),
206	  };
207	
208	  const llmSpan = startSpan({
209	    name: 'llm_call',
210	    parent: parentSpan,
211	    spanType: SpanType.LLM,
212	    startTimeNs: prevBoundaryNs ?? assistantTimestampNs,
213	    inputs: { model, messages },
214	    attributes: { model },
215	  });
216	
217	  const record = turn[assistantIndex];
218	  const tokenUsage = getTokenUsage(record.usageMetadata);
219	  if (tokenUsage) {
220	    llmSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {
221	      [TokenUsageKey.INPUT_TOKENS]: tokenUsage.input,
222	      [TokenUsageKey.OUTPUT_TOKENS]: tokenUsage.output,
223	      [TokenUsageKey.TOTAL_TOKENS]: tokenUsage.total,
