 * Types for Claude Code transcript parsing.
 *
 * Claude Code writes conversation transcripts as JSONL files. Each line is a
 * single entry. The shapes we care about:
 *   - `type: 'user'`      — a user message (or a tool_result carrier)
 *   - `type: 'assistant'` — an assistant response (text and/or tool_use blocks)
 *   - `type: 'progress'`  — an inline sub-agent progress event carrying a
 *                            nested transcript entry in `data.message`
 *   - `type: 'queue-operation'` — a steering-queue mutation (e.g. `enqueue`)
 *
 * Messages use the Anthropic `{role, content}` envelope where `content` is
 * either a plain string or a list of content blocks
 * (`text` / `tool_use` / `tool_result`).
 */

/**
 * A single content block inside an Anthropic-format message `content` array.
 */
export interface ContentBlock {
  type: string;
  /** Present on `text` blocks. */
  text?: string;
  /** Present on `tool_use` blocks. */
  id?: string;
  name?: string;
  input?: Record<string, unknown>;
  /** Present on `tool_result` blocks. */
  tool_use_id?: string;
  content?: unknown;
  is_error?: boolean;
  [key: string]: unknown;
}

/**
 * Token usage reported on an assistant message.
 */
export interface Usage {
  input_tokens?: number;
  output_tokens?: number;
  cache_creation_input_tokens?: number;
  cache_read_input_tokens?: number;
  [key: string]: unknown;
}

/**
 * The Anthropic-style message envelope embedded in a transcript entry.
 */
export interface TranscriptMessage {
  role?: string;
  content?: string | ContentBlock[];
  model?: string;
  usage?: Usage;
  [key: string]: unknown;
}

/**
 * Details attached to a user entry that carries a tool result. For Task
 * (sub-agent) tools this includes the `agentId` used to locate the sub-agent's
 * separate transcript file.
 */
export interface ToolUseResult {
  status?: string;
  agentId?: string;
  totalDurationMs?: number;
  success?: boolean;
  commandName?: string;
  [key: string]: unknown;
}

/**
 * Payload of a `progress` entry — an inline sub-agent event. `message` is a
 * nested transcript entry produced by the sub-agent.
 */
export interface ProgressData {
  type: string;
  agentId: string;
  prompt: string;
  message: TranscriptEntry;
  [key: string]: unknown;
}

/**
 * A single entry in a Claude Code JSONL transcript.
 */
export interface TranscriptEntry {
  type: string;
  message?: TranscriptMessage;
  timestamp?: string | number;
  sessionId?: string;
  agentId?: string;
  version?: string;
  permissionMode?: string;
  isCompactSummary?: boolean;
  toolUseResult?: ToolUseResult;
  /** Present on `progress` entries. */
  parentToolUseID?: string;
  toolUseID?: string;
  data?: ProgressData;
  /** Present on `queue-operation` entries. */
  operation?: string;
  content?: string;
  [key: string]: unknown;
}

/**
 * An Anthropic-format message as reconstructed for LLM span inputs.
 */
export interface AnthropicMessage {
  role: string;
  content: string | ContentBlock[];
  [key: string]: unknown;
}

/**
 * Stop hook input received via stdin.
 */
export interface StopHookInput {
  session_id: string;
  transcript_path: string | null;
  cwd: string;
  hook_event_name: string;
}
