import type { ContentBlock, TranscriptEntry } from './types.js';

export const NANOSECONDS_PER_MS = 1e6;
export const NANOSECONDS_PER_S = 1e9;

/** Read and parse a Claude Code JSONL transcript file, one entry per line. */
export function readTranscript(filePath: string): TranscriptEntry[] {
  const content = readFileSync(filePath, 'utf-8');
  return content
    .split('\n')
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line) as TranscriptEntry);
}

/**
 * Convert a timestamp to nanoseconds since the Unix epoch.
 *
 * ISO date strings are parsed via `Date`. Numeric values are interpreted by
 * magnitude: `>= 1e13` nanoseconds, `>= 1e10` milliseconds, otherwise Unix
 * seconds. Returns `null` for null/undefined/empty-string inputs and for
 * strings that are not valid dates.
 */
export function parseTimestampToNs(ts: string | number | null | undefined): number | null {
  if (ts == null || ts === '') {
    return null;
  }

  if (typeof ts === 'number') {
    if (ts >= 1e13) {
      return Math.floor(ts);
    }
    if (ts >= 1e10) {
      return Math.floor(ts * NANOSECONDS_PER_MS);
    }
    return Math.floor(ts * NANOSECONDS_PER_S);
  }

  const ms = new Date(ts).getTime();
  if (isNaN(ms)) {
    return null;
  }
  return Math.floor(ms * NANOSECONDS_PER_MS);
}

/**
 * Extract plain text from a message `content` value. Strings pass through
 * unchanged; arrays join the `text` fields of all `text` blocks with newlines.
 */
export function extractTextContent(content: string | ContentBlock[] | unknown): string {
  if (Array.isArray(content)) {
    return content
      .filter(
        (part): part is ContentBlock =>
          part != null && typeof part === 'object' && (part as ContentBlock).type === 'text',
      )
      .map((part) => part.text ?? '')
      .join('\n');
  }
  if (typeof content === 'string') {
    return content;
  }
  return '';
}

/**
 * Find the index of the last "real" user message. Skips tool_result carriers,
 * compact-summary entries, and skill-injection messages (text starting with
 * `Base directory:`). Returns `null` for an empty transcript.
 */
export function findLastUserMessageIndex(entries: TranscriptEntry[]): number | null {
  for (let i = entries.length - 1; i >= 0; i--) {
    const entry = entries[i];
    if (entry.type !== 'user') {
      continue;
    }
    if (entry.isCompactSummary === true) {
      continue;
    }

    const content = entry.message?.content;
    if (
      Array.isArray(content) &&
      content.length > 0 &&
      (content[0] as ContentBlock)?.type === 'tool_result'
    ) {
      continue;
    }

    if (extractTextContent(content ?? '').startsWith('Base directory:')) {
      continue;
    }

    return i;
  }
  return null;
}

/**
 * Find the final assistant text response at or after `startIndex`. Returns the
 * extracted text of the last assistant entry that has text content, or `null`.
 */
export function findFinalAssistantResponse(
  entries: TranscriptEntry[],
  startIndex: number,
): string | null {
  let finalResponse: string | null = null;
  for (let i = startIndex; i < entries.length; i++) {
    const entry = entries[i];
    if (entry.type !== 'assistant') {
      continue;
    }
    const text = extractTextContent(entry.message?.content ?? '');
    if (text.trim()) {
      finalResponse = text;
    }
  }
  return finalResponse;
}
