} from './transcript.js';

const MESSAGE_FORMAT_ANTHROPIC = 'anthropic';
const MAX_PREVIEW_LENGTH = 1000;
const DEFAULT_DURATION_NS = NANOSECONDS_PER_S; // 1 second
const TASK_TOOL_NAME = 'Task';
const QUEUE_OPERATION_ENQUEUE = 'enqueue';

const METADATA_KEY_WORKING_DIRECTORY = 'mlflow.trace.working_directory';
const METADATA_KEY_PERMISSION_MODE = 'mlflow.trace.permission_mode';
const METADATA_KEY_CLAUDE_CODE_VERSION = 'mlflow.claude_code_version';

/** Resolved details of a tool_result, keyed by tool_use id. */
interface ToolResultInfo {
  content: unknown;
  isError: boolean;
  timestampNs: number | null;
  agentId?: string;
}

/** Context needed to expand top-level sub-agent (Task) spans. */
interface SubAgentContext {
  progressByParent: Map<string, TranscriptEntry[]>;
  transcriptDir: string;
  transcriptBase: string;
}

/**
 * Process a Claude Code transcript and emit an MLflow trace.
 *
 * Creates no spans (and does not call `flushTraces`) when the file is missing,
 * empty, or contains no real user message.
 */
export async function processTranscript(filePath: string, sessionId: string): Promise<void> {
  try {
    if (!filePath || !existsSync(filePath)) {
      return;
    }

    const transcript = readTranscript(filePath);
    if (transcript.length === 0) {
      return;
    }

    const lastUserIdx = findLastUserMessageIndex(transcript);
    if (lastUserIdx === null) {
      return;
    }

    const lastUserEntry = transcript[lastUserIdx];
    const userPrompt = extractTextContent(lastUserEntry.message?.content ?? '');
    const convStartNs = parseTimestampToNs(lastUserEntry.timestamp);

    const rootSpan = startSpan({
      name: 'claude_code_conversation',
      spanType: SpanType.AGENT,
      inputs: { prompt: userPrompt },
      ...(convStartNs != null ? { startTimeNs: convStartNs } : {}),
    });

    const context: SubAgentContext = {
      progressByParent: buildProgressMap(transcript),
      transcriptDir: dirname(filePath),
      transcriptBase: basename(filePath, '.jsonl'),
    };

    createChildSpans(rootSpan, transcript, lastUserIdx + 1, context);

    const finalResponse = findFinalAssistantResponse(transcript, lastUserIdx + 1);

    // Determine the conversation end time from the last entry, with a default
    // window if timestamps are missing or non-monotonic.
    const lastEntry = transcript[transcript.length - 1];
    let convEndNs = parseTimestampToNs(lastEntry.timestamp);
    if (convEndNs == null || (convStartNs != null && convEndNs <= convStartNs)) {
      convEndNs = convStartNs != null ? convStartNs + 10 * NANOSECONDS_PER_S : null;
    }

    // Attach previews and metadata via the trace manager. Hook-based
    // integrations have no active OTel span context, so `updateCurrentTrace`
    // isn't available; we mutate the in-memory trace info directly (same
    // pattern as the codex/opencode/qwen integrations).
    const traceId = rootSpan.traceId;
    if (traceId) {
      const trace = InMemoryTraceManager.getInstance().getTrace(traceId);
      if (trace) {
        if (userPrompt) {
          trace.info.requestPreview = userPrompt.slice(0, MAX_PREVIEW_LENGTH);
        }
        if (finalResponse) {
          trace.info.responsePreview = finalResponse.slice(0, MAX_PREVIEW_LENGTH);
        }

        const metadata: Record<string, string> = {
          [TraceMetadataKey.TRACE_SESSION]: sessionId,
          [TraceMetadataKey.TRACE_USER]: process.env.USER ?? '',
          [METADATA_KEY_WORKING_DIRECTORY]: process.cwd(),
        };

        const permissionMode = findFirstPermissionMode(transcript);
        if (permissionMode) {
          metadata[METADATA_KEY_PERMISSION_MODE] = permissionMode;
        }
        const version = findFirstVersion(transcript);
        if (version) {
          metadata[METADATA_KEY_CLAUDE_CODE_VERSION] = version;
        }

        trace.info.traceMetadata = { ...trace.info.traceMetadata, ...metadata };
      }
    }

    const outputs: Record<string, unknown> = { status: 'completed' };
    if (finalResponse != null) {
      outputs.response = finalResponse;
    }
    rootSpan.end({ outputs, ...(convEndNs != null ? { endTimeNs: convEndNs } : {}) });

    await flushTraces();
  } catch (err) {
    console.error('[mlflow]', err);
  }
}

/**
 * Create LLM and TOOL child spans for the assistant responses at or after
 * `startIdx`. Text-only assistant turns become LLM spans; tool_use blocks
 * become TOOL spans (with Task tools expanded into nested sub-agent spans when
 * `context` is provided).
 */
function createChildSpans(
  parentSpan: LiveSpan,
  transcript: TranscriptEntry[],
  startIdx: number,
  context?: SubAgentContext,
): void {
  for (let i = startIdx; i < transcript.length; i++) {
    const entry = transcript[i];
    if (entry.type !== 'assistant') {
      continue;
    }

    const msg = entry.message;
    const content = msg?.content;
    const { text, toolUses } = extractContentAndTools(content);

    const timestampNs = parseTimestampToNs(entry.timestamp);
    const nextNs = getNextTimestampNs(transcript, i);
    const durationNs =
      nextNs != null && timestampNs != null ? nextNs - timestampNs : DEFAULT_DURATION_NS;

