,KAAK,CAAC,aAAa,IAAI,CAAC,CAAC;IAE9C,IAAI,CAAC,YAAY,CAAC,uBAAgB,CAAC,WAAW,EAAE;QAC9C,CAAC,oBAAa,CAAC,YAAY,CAAC,EAAE,WAAW;QACzC,CAAC,oBAAa,CAAC,aAAa,CAAC,EAAE,YAAY;QAC3C,CAAC,oBAAa,CAAC,YAAY,CAAC,EAAE,WAAW,GAAG,YAAY;KACzD,CAAC,CAAC;AACL,CAAC;AAED,uEAAuE;AACvE,SAAS,gBAAgB,CAAC,UAA6B;IACrD,MAAM,GAAG,GAAG,IAAI,GAAG,EAA6B,CAAC;IACjD,KAAK,MAAM,KAAK,IAAI,UAAU,EAAE,CAAC;QAC/B,IAAI,KAAK,CAAC,IAAI,KAAK,UAAU,IAAI,KAAK,CAAC,eAAe,EAAE,CAAC;YACvD,MAAM,MAAM,GAAG,GAAG,CAAC,GAAG,CAAC,KAAK,CAAC,eAAe,CAAC,CAAC;YAC9C,IAAI,MAAM,EAAE,CAAC;gBACX,MAAM,CAAC,IAAI,CAAC,KAAK,CAAC,CAAC;YACrB,CAAC;iBAAM,CAAC;gBACN,GAAG,CAAC,GAAG,CAAC,KAAK,CAAC,eAAe,EAAE,CAAC,KAAK,CAAC,CAAC,CAAC;YAC1C,CAAC;QACH,CAAC;IACH,CAAC;IACD,OAAO,GAAG,CAAC;AACb,CAAC;AAED,6EAA6E;AAC7E,SAAS,uBAAuB,CAAC,UAA6B;IAC5D,KAAK,MAAM,KAAK,IAAI,UAAU,EAAE,CAAC;QAC/B,IAAI,KAAK,CAAC,IAAI,KAAK,MAAM,IAAI,KAAK,CAAC,cAAc,EAAE,CAAC;YAClD,OAAO,KAAK,CAAC,cAAc,CAAC;QAC9B,CAAC;IACH,CAAC;IACD,OAAO,SAAS,CAAC;AACnB,CAAC;AAED,iEAAiE;AACjE,SAAS,gBAAgB,CAAC,UAA6B;IACrD,KAAK,MAAM,KAAK,IAAI,UAAU,EAAE,CAAC;QAC/B,IAAI,KAAK,CAAC,OAAO,EAAE,CAAC;YAClB,OAAO,KAAK,CAAC,OAAO,CAAC;QACvB,CAAC;IACH,CAAC;IACD,OAAO,SAAS,CAAC;AACnB,CAAC","names":[],"sources":["/workspace/repo/libs/typescript/integrations/claude-code/src/tracing.ts"],"sourcesContent":["/**\n * MLflow tracing integration for Claude Code.\n *\n * Reads a Claude Code JSONL transcript and emits an MLflow trace shaped as:\n *\n *   AGENT claude_code_conversation\n *   ├─ LLM  llm                 (one per text-only assistant turn)\n *   ├─ TOOL tool_<Name>         (one per tool_use)\n *   └─ TOOL tool_Task           (one per sub-agent invocation)\n *        └─ AGENT subagent_<type>\n *             ├─ LLM  llm\n *             └─ TOOL tool_<Name>\n *\n * The pure parsing helpers live in `./transcript.ts` and mirror the Python\n * integration (`mlflow/claude_code/tracing.py`). This module adds the\n * TypeScript-specific span construction plus sub-agent handling (inline\n * `progress` events and separate `subagent