G,KAAK,CAAC,aAAa,IAAI,CAAC,CAAC;IAE9C,IAAI,CAAC,YAAY,CAAC,uBAAgB,CAAC,WAAW,EAAE;QAC9C,CAAC,oBAAa,CAAC,YAAY,CAAC,EAAE,WAAW;QACzC,CAAC,oBAAa,CAAC,aAAa,CAAC,EAAE,YAAY;QAC3C,CAAC,oBAAa,CAAC,YAAY,CAAC,EAAE,WAAW,GAAG,YAAY;KACzD,CAAC,CAAC;AACL,CAAC;AAED,uEAAuE;AACvE,SAAS,gBAAgB,CAAC,UAA6B;IACrD,MAAM,GAAG,GAAG,IAAI,GAAG,EAA6B,CAAC;IACjD,KAAK,MAAM,KAAK,IAAI,UAAU,EAAE,CAAC;QAC/B,IAAI,KAAK,CAAC,IAAI,KAAK,UAAU,IAAI,KAAK,CAAC,eAAe,EAAE,CAAC;YACvD,MAAM,MAAM,GAAG,GAAG,CAAC,GAAG,CAAC,KAAK,CAAC,eAAe,CAAC,CAAC;YAC9C,IAAI,MAAM,EAAE,CAAC;gBACX,MAAM,CAAC,IAAI,CAAC,KAAK,CAAC,CAAC;YACrB,CAAC;iBAAM,CAAC;gBACN,GAAG,CAAC,GAAG,CAAC,KAAK,CAAC,eAAe,EAAE,CAAC,KAAK,CAAC,CAAC,CAAC;YAC1C,CAAC;QACH,CAAC;IACH,CAAC;IACD,OAAO,GAAG,CAAC;AACb,CAAC;AAED,6EAA6E;AAC7E,SAAS,uBAAuB,CAAC,UAA6B;IAC5D,KAAK,MAAM,KAAK,IAAI,UAAU,EAAE,CAAC;QAC/B,IAAI,KAAK,CAAC,IAAI,KAAK,MAAM,IAAI,KAAK,CAAC,cAAc,EAAE,CAAC;YAClD,OAAO,KAAK,CAAC,cAAc,CAAC;QAC9B,CAAC;IACH,CAAC;IACD,OAAO,SAAS,CAAC;AACnB,CAAC;AAED,iEAAiE;AACjE,SAAS,gBAAgB,CAAC,UAA6B;IACrD,KAAK,MAAM,KAAK,IAAI,UAAU,EAAE,CAAC;QAC/B,IAAI,KAAK,CAAC,OAAO,EAAE,CAAC;YAClB,OAAO,KAAK,CAAC,OAAO,CAAC;QACvB,CAAC;IACH,CAAC;IACD,OAAO,SAAS,CAAC;AACnB,CAAC","names":[],"sources":["/workspace/repo/libs/typescript/integrations/claude-code/src/tracing.ts"],"sourcesContent":["/**\n * MLflow tracing integration for Claude Code.\n *\n * Reads a Claude Code JSONL transcript and emits an MLflow trace shaped as:\n *\n *   AGENT claude_code_conversation\n *   ├─ LLM  llm                 (one per text-only assistant turn)\n *   ├─ TOOL tool_<Name>         (one per tool_use)\n *   └─ TOOL tool_Task           (one per sub-agent invocation)\n *        └─ AGENT subagent_<type>\n *             ├─ LLM  llm\n *             └─ TOOL tool_<Name>\n *\n * The pure parsing helpers live in `./transcript.ts` and mirror the Python\n * integration (`mlflow/claude_code/tracing.py`). This module adds the\n * TypeScript-specific span construction plus sub-agent handling (inline\n * `progress` events and separate `subagents/agent-<id>.jsonl` files).\n */\n\nimport { existsSync } from 'node:fs';\nimport { basename, dirname, join } from 'node:path';\n\nimport {\n  startSpan,\n  flushTraces,\n  InMemoryTraceManager,\n  SpanStatusCode,\n  SpanType,\n  SpanAttributeKey,\n  TraceMetadataKey,\n  TokenUsageKey,\n  type LiveSpan,\n} from '@mlflow/core';\n\nimport type {\n  AnthropicMessage,\n  ContentBlock,\n  TranscriptEntry,\n  TranscriptMessage,\n  Usage,\n} from './types.js';\nimport {\n  NANOSECONDS_PER_S,\n  extractTextContent,\n  findFinalAssistantResponse,\n  findLastUserMessageIndex,\n  parseTimestampToNs,\n  readTranscript,\n} from './transcript.js';\n\nconst MESSAGE_FORMAT_ANTHROPIC = 'anthropic';\nconst MAX_PREVIEW_LENGTH = 1000;\nconst DEFAULT_DURATION_NS = NANOSECONDS_PER_S; // 1 second\nconst TASK_TOOL_NAME = 'Task';\nconst QUEUE_OPERATION_ENQUEUE = 'enqueue';\n\nconst METADATA_KEY_WORKING_DIRECTORY = 'mlflow.trace.working_directory';\nconst METADATA_KEY_PERMISSION_MODE = 'mlflow.trace.permission_mode';\nconst METADATA_KEY_CLAUDE_CODE_VERSION = 'mlflow.claude_code_version';\n\n/** Resolved details of a tool_result, keyed by tool_use id. */\ninterface ToolResultInfo {\n  content: unknown;\n  isError: boolean;\n  timestampNs: number | null;\n  agentId?: string;\n}\n\n/** Context needed to expand top-level sub-agent (Task) spans. */\ninterface SubAgentContext {\n  progressByParent: Map<string, TranscriptEntry[]>;\n  transcriptDir: string;\n  transcriptBase: string;\n}\n\n/**\n * Process a Claude Code transcript and emit an MLflow trace.\n *\n * Creates no spans (and does not call `flushTraces`) when the file is missing,\n * empty, or contains no real user message.\n */\nexport async function processTranscript(filePath: string, sessionId: string): Promise<void> {\n  try {\n    if (!filePath || !existsSync(filePath)) {\n      return;\n    }\n\n    const transcript = readTranscript(filePath);\n    if (transcript.length === 0) {\n      return;\n    }\n\n    const lastUserIdx = findLastUserMessageIndex(transcript);\n    if (lastUserIdx == null) {\n      return;\n    }\n\n    const lastUserEntry = transcript[lastUserIdx];\n    const userPrompt = extractTextContent(lastUserEntry.message?.content ?? '');\n    const convStartNs = parseTimestampToNs(lastUserEntry.timestamp);\n\n    const rootSpan = startSpan({\n      name: 'claude_code_conversation',\n      spanType: SpanType.AGENT,\n      inputs: { prompt: userPrompt },\n      ...(convStartNs != null ? { startTimeNs: convStartNs } : {}),\n    });\n\n    const context: SubAgentContext = {\n      progressByParent: buildProgressMap(transcript),\n      transcriptDir: dirname(filePath),\n      transcriptBase: basename(filePath, '.jsonl'),\n    };\n\n    createChildSpans(rootSpan, transcript, lastUserIdx + 1, context);\n\n    const finalResponse = findFinalAssistantResponse(transcript, lastUserIdx + 1);\n\n    // Determine the conversation end time from the last entry, with a default\n    // window if timestamps are missing or non-monotonic.\n    const lastEntry = transcript[transcript.length - 1];\n    let convEndNs = parseTimestampToNs(lastEntry.timestamp);\n    if (convEndNs == null || (convStartNs != null && convEndNs <= convStartNs)) {\n      convEndNs = convStartNs != null ? convStartNs + 10 * NANOSECONDS_PER_S : null;\n    }\n\n    // Attach previews and metadata via the trace manager. Hook-based\n    // integrations have no active OTel span context, so `updateCurrentTrace`\n    // isn't available; we mutate the in-memory trace info directly (same\n    // pattern as the codex/opencode/qwen integrations).\n    const traceId = rootSpan.traceId;\n    if (traceId) {\n      const trace = InMemoryTraceManager.getInstance().getTrace(traceId);\n      if (trace) {\n        if (userPrompt) {\n          trace.info.requestPreview = userPrompt.slice(0, MAX_PREVIEW_LENGTH);\n        }\n        if (finalResponse) {\n          trace.info.responsePreview = finalResponse.slice(0, MAX_PREVIEW_LENGTH);\n        }\n\n        const metadata: Record<string, string> = {\n          [TraceMetadataKey.TRACE_SESSION]: sessionId,\n          [TraceMetadataKey.TRACE_USER]: process.env.USER ?? '',\n          [METADATA_KEY_WORKING_DIRECTORY]: process.cwd(),\n        };\n\n        const permissionMode = findFirstPermissionMode(transcript);\n        if (permissionMode) {\n          metadata[METADATA_KEY_PERMISSION_MODE] = permissionMode;\n        }\n        const version = findFirstVersion(transcript);\n        if (version) {\n          metadata[METADATA_KEY_CLAUDE_CODE_VERSION] = version;\n        }\n\n        trace.info.traceMetadata = { ...trace.info.traceMetadata, ...metadata };\n      }\n    }\n\n    const outputs: Record<string, unknown> = { status: 'completed' };\n    if (finalResponse != null) {\n      outputs.response = finalResponse;\n    }\n    rootSpan.end({ outputs, ...(convEndNs != null ? { endTimeNs: convEndNs } : {}) });\n\n    await flushTraces();\n  } catch (err) {\n    console.error('[mlflow]', err);\n  }\n}\n\n/**\n * Create LLM and TOOL child spans for the assistant responses at or after\n * `startIdx`. Text-only assistant turns become LLM spans; tool_use blocks\n * become TOOL spans (with Task tools expanded into nested sub-agent spans when\n * `context` is provided).\n */\nfunction createChildSpans(\n  parentSpan: LiveSpan,\n  transcript: TranscriptEntry[],\n  startIdx: number,\n  context?: SubAgentContext,\n): void {\n  for (let i = startIdx; i < transcript.length; i++) {\n    const entry = transcript[i];\n    if (entry.type !== 'assistant') {\n      continue;\n    }\n\n    const msg = entry.message;\n    const content = msg?.content;\n    const { text, toolUses } = extractContentAndTools(content);\n\n    const timestampNs = parseTimestampToNs(entry.timestamp);\n    const nextNs = getNextTimestampNs(transcript, i);\n    const durationNs =\n      nextNs != null && timestampNs != null ? nextNs - timestampNs : DEFAULT_DURATION_NS;\n\n    // Text-only assistant turns render as an LLM span.\n    if (text.trim() && toolUses.length === 0) {\n      createLlmSpan(parentSpan, transcript, i, timestampNs, durationNs, msg, content);\n    }\n\n    if (toolUses.length > 0) {\n      createToolSpans(parentSpan, transcript, i, timestampNs, durationNs, toolUses, context);\n    }\n  }\n}\n\nfunction createLlmSpan(\n  parentSpan: LiveSpan,\n  transcript: TranscriptEntry[],\n  index: number,\n  timestampNs: number | null,\n  durationNs: number,\n  msg: TranscriptMessage | undefined,\n  content: string | ContentBlock[] | undefined,\n): void {\n  const model = msg?.model ?? 'unknown';\n  const messages = getInputMessages(transcript, index);\n\n  const llmSpan = startSpan({\n    name: 'llm',\n    parent: parentSpan,\n    spanType: SpanType.LLM,\n    ...(timestampNs != null ? { startTimeNs: timestampNs } : {}),\n    inputs: { model, messages },\n    attributes: { model, [SpanAttributeKey.MESSAGE_FORMAT]: MESSAGE_FORMAT_ANTHROPIC },\n  });\n\n  setTokenUsage(llmSpan, msg?.usage);\n\n  llmSpan.end({\n    outputs: { type: 'message', role: 'assistant', content },\n    ...(timestampNs != null ? { endTimeNs: timestampNs + durationNs } : {}),\n  });\n}\n\nfunction createToolSpans(\n  parentSpan: LiveSpan,\n  transcript: TranscriptEntry[],\n  index: number,\n  timestampNs: number | null,\n  durationNs: number,\n  toolUses: ContentBlock[],\n  context?: SubAgentContext,\n): void {\n  const toolResults = findToolResults(transcript, index);\n  const toolDurationNs = Math.floor(durationNs / toolUses.length);\n\n  toolUses.forEach((toolUse, idx) => {\n    const toolStartNs = timestampNs != null ? timestampNs + idx * toolDurationNs : null;\n    const toolName = (toolUse.name as string) ?? 'unknown';\n    const toolId = (toolUse.id as string) ?? '';\n    const resultInfo = toolResults.get(toolId);\n    const resultContent = resultInfo ? resultInfo.content : 'No result found';\n\n    const toolSpan = startSpan({\n      name: `tool_${toolName}`,\n      parent: parentSpan,\n      spanType: SpanType.TOOL,\n      ...(toolStartNs != null ? { startTimeNs: toolStartNs } : {}),\n      inputs: toolUse.input ?? {},\n      attributes: { tool_name: toolName, tool_id: toolId },\n    });\n\n    if (resultInfo?.isError) {\n      const message =\n        typeof resultContent === 'string' && resultContent.includes(\"doesn't want to proceed\")\n          ? resultContent\n          : \"The user doesn't want to proceed with this tool use.\";\n      toolSpan.recordException(new Error(message));\n      toolSpan.setStatus(SpanStatusCode.ERROR, message);\n    }\n\n    if (toolName === TASK_TOOL_NAME && context) {\n      createSubAgentSpan(toolSpan, toolUse, resultInfo, context);\n    }\n\n    toolSpan.end({\n      outputs: { result: resultContent },\n      ...(toolStartNs != null ? { endTimeNs: toolStartNs + toolDurationNs } : {}),\n    });\n  });\n}\n\n/**\n * Expand a Task tool call into a nested `subagent_<type>` AGENT span, sourcing\n * the sub-agent's turns from inline `progress` events or, failing that, a\n * separate `subagents/agent-<agentId>.jsonl` file.\n */\nfunction createSubAgentSpan(\n  taskSpan: LiveSpan,\n  toolUse: ContentBlock,\n  resultInfo: ToolResultInfo | undefined,\n  context: SubAgentContext,\n): void {\n  const input: Record<string, unknown> = toolUse.input ?? {};\n  const subagentType = (input.subagent_type as string) ?? 'unknown';\n  const toolId = (toolUse.id as string) ?? '';\n\n  let subEntries: TranscriptEntry[] | null = null;\n\n  const progressEntries = context.progressByParent.get(toolId);\n  if (progressEntries && progressEntries.length > 0) {\n    subEntries = progressEntries\n      .map((entry) => entry.data?.message)\n      .filter((message): message is TranscriptEntry => message != null);\n  } else if (resultInfo?.agentId) {\n    const subPath = join(\n      context.transcriptDir,\n      context.transcriptBase,\n      'subagents',\n      `agent-${resultInfo.agentId}.jsonl`,\n    );\n    if (existsSync(subPath)) {\n      try {\n        subEntries = readTranscript(subPath);\n      } catch {\n        subEntries = null;\n      }\n    }\n  }\n\n  if (!subEntries || subEntries.length === 0) {\n    return;\n  }\n\n  const subStartNs = parseTimestampToNs(subEntries[0].timestamp);\n  const subAgentSpan = startSpan({\n    name: `subagent_${subagentType}`,\n    parent: taskSpan,\n    spanType: SpanType.AGENT,\n    ...(subStartNs != null ? { startTimeNs: subStartNs } : {}),\n    inputs: { prompt: (input.prompt as string) ?? '' },\n  });\n\n  createChildSpans(subAgentSpan, subEntries, 0);\n\n  const finalResponse = findFinalAssistantResponse(subEntries, 0);\n  const subEndNs = parseTimestampToNs(subEntries[subEntries.length - 1].timestamp);\n  const outputs: Record<string, unknown> = { status: 'completed' };\n  if (finalResponse != null) {\n    outputs.response = finalResponse;\n  }\n  subAgentSpan.end({ outputs, ...(subEndNs != null ? { endTimeNs: subEndNs } : {}) });\n}\n\n/**\n * Split assistant message content into concatenated text and tool_use blocks.\n */\nfunction extractContentAndTools(content: string | ContentBlock[] | undefined): {\n  text: string;\n  toolUses: ContentBlock[];\n} {\n  let text = '';\n  const toolUses: ContentBlock[] = [];\n\n  if (Array.isArray(content)) {\n    for (const part of content) {\n      if (part != null && typeof part === 'object') {\n        if (part.type === 'text') {\n          text += part.text ?? '';\n        } else if (part.type === 'tool_use') {\n          toolUses.push(part);\n        }\n      }\n    }\n  } else if (typeof content === 'string') {\n    text = content;\n  }\n\n  return { text, toolUses };\n}\n\n/** Find the timestamp (ns) of the next entry after `index` that has one. */\nfunction getNextTimestampNs(transcript: TranscriptEntry[], index: number): number | null {\n  for (let i = index + 1; i < transcript.length; i++) {\n    const ns = parseTimestampToNs(transcript[i].timestamp);\n    if (ns != null) {\n      return ns;\n    }\n  }\n  return null;\n}\n\n/**\n * Collect tool_result blocks that follow the assistant response at `startIdx`,\n * keyed by their `tool_use_id`.\n */\nfunction findToolResults(\n  transcript: TranscriptEntry[],\n  startIdx: number,\n): Map<string, ToolResultInfo> {\n  const results = new Map<string, ToolResultInfo>();\n\n  for (let i = startIdx + 1; i < transcript.length; i++) {\n    const entry = transcript[i];\n    if (entry.type !== 'user') {\n      continue;\n    }\n    const content = entry.message?.content;\n    if (!Array.isArray(content)) {\n      continue;\n    }\n    for (const part of content) {\n      if (part != null && typeof part === 'object' && part.type === 'tool_result') {\n        const toolUseId = part.tool_use_id;\n        if (toolUseId) {\n          results.set(toolUseId, {\n            content: part.content ?? '',\n            isError: part.is_error === true,\n            timestampNs: parseTimestampToNs(entry.timestamp),\n            agentId: entry.toolUseResult?.agentId,\n          });\n        }\n      }\n    }\n  }\n\n  return results;\n}\n\n/**\n * Reconstruct the Anthropic-format messages leading up to the assistant\n * response at `currentIdx`, walking back to the previous text-bearing\n * assistant turn. Steering-queue `enqueue` operations are surfaced as user\n * messages; other queue operations are ignored.\n */\nfunction getInputMessages(transcript: TranscriptEntry[], currentIdx: number): AnthropicMessage[] {\n  const messages: AnthropicMessage[] = [];\n\n  for (let i = currentIdx - 1; i >= 0; i--) {\n    const entry = transcript[i];\n    const msg = entry.message;\n\n    if (entry.type === 'assistant') {\n      const content = msg?.content;\n      let hasText = false;\n      if (typeof content === 'string') {\n        hasText = content.trim() !== '';\n      } else if (Array.isArray(content)) {\n        hasText = content.some(\n          (part) => part != null && typeof part === 'object' && part.type === 'text',\n        );\n      }\n      