   spanType: options.spanType ?? 'UNKNOWN',\n      inputs: options.inputs ?? {},\n      outputs: {},\n      attributes: { ...(options.attributes ?? {}) },\n      startTimeNs: options.startTimeNs ?? null,\n      endTimeNs: null,\n      statusCode: null,\n      statusMessage: null,\n      exceptions: [] as Error[],\n      setAttribute: jest.fn((k: string, v: any) => { span.attributes[k] = v; }),\n      setStatus: jest.fn((c: string, m?: string) => { span.statusCode = c; span.statusMessage = m ?? null; }),\n      recordException: jest.fn((e: Error) => { span.exceptions.push(e); }),\n      end: jest.fn((opts?: any) => {\n        if (opts?.outputs != null) span.outputs = opts.outputs;\n        if (opts?.endTimeNs != null) span.endTimeNs = opts.endTimeNs;\n      }),\n    };\n    mockSpans[id] = span;\n    return span;\n  }),\n  flushTraces: jest.fn().mockResolvedValue(undefined),\n  SpanStatusCode: { OK: 'STATUS_CODE_OK', ERROR: 'STATUS_CODE_ERROR', UNSET: 'STATUS_CODE_UNSET' },\n  SpanType: { LLM: 'LLM', AGENT: 'AGENT', TOOL: 'TOOL', UNKNOWN: 'UNKNOWN' },\n  SpanAttributeKey: { TOKEN_USAGE: 'mlflow.chat.tokenUsage', MESSAGE_FORMAT: 'mlflow.message.format' },\n  TraceMetadataKey: { TRACE_SESSION: 'mlflow.trace.session', TRACE_USER: 'mlflow.trace.user' },\n  TokenUsageKey: { INPUT_TOKENS: 'input_tokens', OUTPUT_TOKENS: 'output_tokens', TOTAL_TOKENS: 'total_tokens' },\n  InMemoryTraceManager: { getInstance: jest.fn(() => ({ getTrace: jest.fn(() => ({ info: mockTraceInfo })) })) },\n}));\n\nimport { processTranscript } from '/workspace/repo/libs/typescript/integrations/claude-code/src/tracing';\n\nconst DIR = '/tmp/ccv/fixtures';\nfunction writeJsonl(name: string, entries: any[]) {\n  const p = join(DIR, name);\n  writeFileSync(p, entries.map((e) => JSON.stringify(e)).join('\\n') + '\\n');\n  return p;\n}\nconst spans = () => Object.values(mockSpans) as any[];\nconst byType = (t: string) => spans().filter((s) => s.spanType === t);\nconst root = () => spans().find((s) => s.parentId == null);\n\nbeforeEach(() => {\n  spanCounter = 0;\n  Object.keys(mockSpans).forEach((k) => delete mockSpans[k]);\n  mockTraceInfo.traceMetadata = {};\n  mockTraceInfo.requestPreview = undefined;\n  mockTraceInfo.responsePreview = undefined;\n  jest.clearAllMocks();\n});\n\ntest('basic: root + one llm', async () => {\n  const p = writeJsonl('basic.jsonl', [\n    { type: 'user', message: { role: 'user', content: 'what is 2+2' }, timestamp: '2026-04-05T10:00:00Z', permissionMode: 'default', version: '1.2.3' },\n    { type: 'assistant', message: { role: 'assistant', model: 'claude-x', content: [{ type: 'text', text: '4' }], usage: { input_tokens: 100, cache_creation_input_tokens: 5, cache_read_input_tokens: 999, output_tokens: 10 } }, timestamp: '2026-04-05T10:00:02Z' },\n  ]);\n  await processTranscript(p, 'sess-1');\n  const r = root();\n  expect(r.name).toBe('claude_code_conversation');\n  expect(r.spanType).toBe('AGENT');\n  expect(r.inputs).toEqual({ prompt: 'what is 2+2' });\n  const endArgs = (r.end as jest.Mock).mock.calls[0][0];\n  expect(endArgs.outputs).toEqual({ status: 'completed', response: '4' });\n  const llm = byType('LLM');\n  expect(llm.length).toBe(1);\n  expect(llm[0].name).toBe('llm');\n  expect(llm[0].parentId).toBe(r.spanId);\n  expect(llm[0].attributes['mlflow.message.format']).toBe('anthropic');\n  const llmEnd = (llm[0].end as jest.Mock).mock.calls[0][0];\n  expect(llmEnd.outputs).toEqual({ type: 'message', role: 'assistant', content: [{ type: 'text', text: '4' }] });\n  // token usage: input=100+5=105, out=10, total=115\n  expect(llm[0].setAttribute).toHaveBeenCalledWith('mlflow.chat.tokenUsage', { input_tokens: 105, output_tokens: 10, total_tokens: 115 });\n  // metadata\n  expect(mockTraceInfo.traceMetadata['mlflow.trace.session']).toBe('sess-1');\n  expect(mockTraceInfo.traceMetadata['mlflow.trace.working_directory']).toBeDefined();\n  expect(mockTraceInfo.traceMetadata['mlflow.trace.permission_mode']).toBe('default');\n  expect(mockTraceInfo.traceMetadata['mlflow.claude_code_version']).toBe('1.2.3');\n  expect(mockTraceInfo.requestPreview).toBe('what is 2+2');\n  expect(mockTraceInfo.responsePreview).toBe('4');\n});\n\ntest('tool call: tool span + result + timing', async () => {\n  const p = writeJsonl('tool.jsonl', [\n    { type: 'user', message: { role: 'user', content: 'list files' }, timestamp: '2026-04-05T10:00:00Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'tool_use', id: 't1', name: 'LS', input: { path: '.' } }] }, timestamp: '2026-04-05T10:00:01Z' },\n    { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 't1', content: 'a\\nb' }] }, timestamp: '2026-04-05T10:00:02Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'done' }] }, timestamp: '2026-04-05T10:00:03Z' },\n  ]);\n  await processTranscript(p, 'sess-2');\n  const tools = byType('TOOL');\n  expect(tools.length).toBe(1);\n  expect(tools[0].name).toBe('tool_LS');\n  expect(tools[0].inputs).toEqual({ path: '.' });\n  expect(tools[0].attributes.tool_name).toBe('LS');\n  expect(tools[0].attributes.tool_id).toBe('t1');\n  const te = (tools[0].end as jest.Mock).mock.calls[0][0];\n  expect(te.outputs).toEqual({ result: 'a\\nb' });\n  // one LLM (text-only final)\n  expect(byType('LLM').length).toBe(1);\n});\n\ntest('error tool records exception', async () => {\n  const p = writeJsonl('err.jsonl', [\n    { type: 'user', message: { role: 'user', content: 'rm stuff' }, timestamp: '2026-04-05T10:00:00Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'tool_use', id: 't1', name: 'Bash', input: { cmd: 'rm' } }] }, timestamp: '2026-04-05T10:00:01Z' },\n    { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 't1', content: 'The user doesn\\'t want to proceed with this tool use.', is_error: true }] }, timestamp: '2026-04-05T10:00:02Z' },\n  ]);\n  await processTranscript(p, 'sess-3');\n  const tool = byType('TOOL')[0];\n  expect(tool.recordException).toHaveBeenCalled();\n  expect(tool.exceptions[0].message).toContain(\"doesn't want to proceed\");\n  expect(tool.statusCode).toBe('STATUS_CODE_ERROR');\n});\n\ntest('enqueue steer message included in LLM inputs', async () => {\n  const p = writeJsonl('steer.jsonl', [\n    { type: 'user', message: { role: 'user', content: 'Tell me about Python.' }, timestamp: '2025-01-15T10:00:00Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'Python is great.' }] }, timestamp: '2025-01-15T10:00:01Z' },\n    { type: 'queue-operation', operation: 'enqueue', content: 'also tell me about Java', timestamp: '2025-01-15T10:00:02Z' },\n    { type: 'queue-operation', operation: 'remove', timestamp: '2025-01-15T10:00:03Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'Java too.' }] }, timestamp: '2025-01-15T10:00:04Z' },\n  ]);\n  await processTranscript(p, 'sess-4');\n  const llm = byType('LLM');\n  expect(llm.length).toBe(2);\n  const second = llm[1];\n  const steer = second.inputs.messages.filter((m: any) => m.content === 'also tell me about Java');\n  expect(steer.length).toBe(1);\n  expect(steer[0].role).toBe('user');\n});\n\ntest('inline subagent progress', async () => {\n  const p = writeJsonl('sub-inline.jsonl', [\n    { type: 'user', message: { role: 'user', content: 'do research' }, timestamp: '2026-04-05T10:00:00Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'tool_use', id: 'task1', name: 'Task', input: { subagent_type: 'researcher', prompt: 'go' } }] }, timestamp: '2026-04-05T10:00:01Z' },\n    { type: 'progress', parentToolUseID: 'task1', toolUseID: 'task1', data: { type: 'progress', agentId: 'ag1', prompt: 'go', message: { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'sub thinking' }] }, timestamp: '2026-04-05T10:00:01.5Z' } } },\n    { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'task1', content: 'sub done' }] }, timestamp: '2026-04-05T10:00:03Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'all done' }] }, timestamp: '2026-04-05T10:00:04Z' },\n  ]);\n  await processTranscript(p, 'sess-5');\n  const taskSpan = spans().find((s) => s.name === 'tool_Task');\n  expect(taskSpan).toBeDefined();\n  const sub = spans().find((s) => s.name === 'subagent_researcher');\n  expect(sub).toBeDefined();\n  expect(sub.spanType).toBe('AGENT');\n  expect(sub.parentId).toBe(taskSpan.spanId);\n  // sub-agent llm child\n  const subLlm = spans().find((s) => s.spanType === 'LLM' && s.parentId === sub.spanId);\n  expect(subLlm).toBeDefined();\n});\n\ntest('file-based subagent', async () => {\n  mkdirSync(join(DIR, 'sub-file', 'subagents'), { recursive: true });\n  writeFileSync(join(DIR, 'sub-file', 'subagents', 'agent-XYZ.jsonl'),\n    [\n      { type: 'user', message: { role: 'user', content: 'sub prompt' }, timestamp: '2026-04-05T10:00:01Z' },\n      { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'sub answer' }] }, timestamp: '2026-04-05T10:00:02Z' },\n    ].map((e) => JSON.stringify(e)).join('\\n') + '\\n');\n  const p = writeJsonl('sub-file.jsonl', [\n    { type: 'user', message: { role: 'user', content: 'delegate' }, timestamp: '2026-04-05T10:00:00Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'tool_use', id: 'task9', name: 'Task', input: { subagent_type: 'coder', prompt: 'go' } }] }, timestamp: '2026-04-05T10:00:01Z' },\n    { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'task9', content: 'ok' }] }, toolUseResult: { agentId: 'XYZ', status: 'success' }, timestamp: '2026-04-05T10:00:03Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'final' }] }, timestamp: '2026-04-05T10:00:04Z' },\n  ]);\n  await processTranscript(p, 'sess-6');\n  const sub = spans().find((s) => s.name === 'subagent_coder');\n  expect(sub).toBeDefined();\n  const subLlm = spans().find((s) => s.spanType === 'LLM' && s.parentId === sub.spanId);\n  expect(subLlm).toBeDefined();\n});\n\ntest('parallel Task tools each get result', async () => {\n  const p = writeJsonl('parallel.jsonl', [\n    { type: 'user', message: { role: 'user', content: 'two tasks' }, timestamp: '2026-04-05T10:00:00Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [\n      { type: 'tool_use', id: 'a', name: 'Task', input: { subagent_type: 'x', prompt: 'p1' } },\n      { type: 'tool_use', id: 'b', name: 'Task', input: { subagent_type: 'y', prompt: 'p2' } },\n    ] }, timestamp: '2026-04-05T10:00:01Z' },\n    { type: 'user', message: { role: 'user', content: [\n      { type: 'tool_result', tool_use_id: 'a', content: 'resA' },\n      { type: 'tool_result', tool_use_id: 'b', content: 'resB' },\n    ] }, timestamp: '2026-04-05T10:00:02Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'both done' }] }, timestamp: '2026-04-05T10:00:03Z' },\n  ]);\n  await processTranscript(p, 'sess-7');\n  const taskSpans = spans().filter((s) => s.name === 'tool_Task');\n  expect(taskSpans.length).toBe(2);\n  const outs = taskSpans.map((s) => (s.end as jest.Mock).mock.calls[0][0].outputs.result).sort();\n  expect(outs).toEqual(['resA', 'resB']);\n});\n\ntest('no spans for missing/empty/no-user', async () => {\n  const { startSpan } = require('@mlflow/core');\n  await processTranscript('/tmp/ccv/does-not-exist.jsonl', 's');\n  const empty = writeJsonl('empty.jsonl', []);\n  await processTranscript(empty, 's');\n  const nouser = writeJsonl('nouser.jsonl', [{ type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'hi' }] }, timestamp: '2026-04-05T10:00:00Z' }]);\n  await processTranscript(nouser, 's');\n  expect((startSpan as jest.Mock)).not.toHaveBeenCalled();\n});\n"],"version":3}
